def split_words(txt):
    txt = txt.replace(',', ' ').replace('!', '').replace('?', '').replace('.', '')
    words = txt.split()
    if len(words) == 1 and len(txt) > 1:
        result = 0
        for i in range(len(txt)):
            if i % 4 == 0 and i % 3 != 0 and ord(txt[i].lower()) % 2 != 0:
                result += 1
        return result
    else:
        return words
